import { useCallback } from 'react';

interface UsePlayerControlsProps {
  videoRef: React.RefObject<HTMLVideoElement> | null;
  youtubeContainerRef: React.RefObject<HTMLDivElement> | null;
  vimeoContainerRef: React.RefObject<HTMLDivElement>  | null;
  playerState: any;
}
 
export const usePlayerControls = ({ 
  videoRef, 
  youtubeContainerRef, 
  vimeoContainerRef, 
  playerState 
}: UsePlayerControlsProps) => {
  
  const handlePlay = useCallback(async () => {
    if (playerState.playerType === 'youtube' && playerState.youtubePlayer) {
      playerState.youtubePlayer.play();
    } else if (playerState.playerType === 'vimeo' && playerState.vimeoPlayer) {
      await playerState.vimeoPlayer.play();
    } else if (videoRef.current) {
      await videoRef.current.play();
    }
  }, [playerState, videoRef]);

  const handlePause = useCallback(async () => {
    if (playerState.playerType === 'youtube' && playerState.youtubePlayer) {
      playerState.youtubePlayer.pause();
    } else if (playerState.playerType === 'vimeo' && playerState.vimeoPlayer) {
      await playerState.vimeoPlayer.pause();
    } else if (videoRef.current) {
      videoRef.current.pause();
    }
  }, [playerState, videoRef]);
 
  const handleSeek = useCallback(async (time: number) => {
    if (playerState.playerType === 'youtube' && playerState.youtubePlayer) {
      playerState.youtubePlayer.seekTo(time);
    } else if (playerState.playerType === 'vimeo' && playerState.vimeoPlayer) {
      await playerState.vimeoPlayer.seekTo(time);
    } else if (videoRef.current) {
      videoRef.current.currentTime = time;
    }
  }, [playerState, videoRef]);

  const handleVolumeChange = useCallback(async (newVolume: number) => {
    playerState.setVolume(newVolume);
    if (playerState.playerType === 'youtube' && playerState.youtubePlayer) {
      playerState.youtubePlayer.setVolume(newVolume);
    } else if (playerState.playerType === 'vimeo' && playerState.vimeoPlayer) {
      await playerState.vimeoPlayer.setVolume(newVolume);
    } else if (videoRef.current) {
      videoRef.current.volume = newVolume;
    }
  }, [playerState, videoRef]);

  const handleMuteToggle = useCallback(async () => {
    const newMuted = !playerState.isMuted;
    playerState.setIsMuted(newMuted);
    
    if (playerState.playerType === 'youtube' && playerState.youtubePlayer) {
      if (newMuted) {
        playerState.youtubePlayer.mute();
      } else {
        playerState.youtubePlayer.unmute();
      }
    } else if (playerState.playerType === 'vimeo' && playerState.vimeoPlayer) {
      if (newMuted) {
        await playerState.vimeoPlayer.mute();
      } else {
        await playerState.vimeoPlayer.unmute();
      }
    } else if (videoRef.current) {
      videoRef.current.muted = newMuted;
    }
  }, [playerState, videoRef]);

  const handlePlaybackRateChange = useCallback(async (rate: number) => {
    playerState.setPlaybackRate(rate);
    if (playerState.playerType === 'youtube' && playerState.youtubePlayer) {
      playerState.youtubePlayer.setPlaybackRate(rate);
    } else if (playerState.playerType === 'vimeo' && playerState.vimeoPlayer) {
      await playerState.vimeoPlayer.setPlaybackRate(rate);
    } else if (videoRef.current) {
      videoRef.current.playbackRate = rate;
    }
  }, [playerState, videoRef]);

  const handleQualityChange = useCallback((quality: string) => {
    const selectedOption = playerState.availableQualities.find((q: any) => q.value === quality);
    if (selectedOption && (playerState.playerType === 'video' || playerState.playerType === 'btag')) {
      const currentTime = videoRef.current?.currentTime || 0;
      const wasPlaying = playerState.isPlaying;
      
      playerState.setVideoSrc(selectedOption.url);
      playerState.setSelectedQuality(quality);
      
      // Restore time and playing state after source change
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.currentTime = currentTime;
          if (wasPlaying) {
            videoRef.current.play();
          }
        }
      }, 100);
    }
  }, [playerState, videoRef]);

  const handleFullscreen = useCallback(() => {
    const element = playerState.playerType === 'youtube' ? youtubeContainerRef.current : 
                   playerState.playerType === 'vimeo' ? vimeoContainerRef.current : 
                   videoRef.current;
                   
    if (element) {
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else {
        element.requestFullscreen();
      }
    }
  }, [playerState.playerType, youtubeContainerRef, vimeoContainerRef, videoRef]);

  const handlePiP = useCallback(() => {
    if (videoRef.current && (videoRef.current as any).requestPictureInPicture && 
        (playerState.playerType === 'video' || playerState.playerType === 'btag')) {
      (videoRef.current as any).requestPictureInPicture();
    }
  }, [videoRef, playerState.playerType]);

  const handleChapterClick = useCallback((startTime: number) => {
    handleSeek(startTime);
  }, [handleSeek]);

  return {
    handlePlay,
    handlePause,
    handleSeek,
    handleVolumeChange,
    handleMuteToggle,
    handlePlaybackRateChange,
    handleQualityChange,
    handleFullscreen,
    handlePiP,
    handleChapterClick
  };
};